with latest as (select * from shipments qualify row_number() over (partition by status order by cost nulls first, id) = 1) select date_trunc('quarter', shipped_date) as quarter_start, max(cost) filter (where status = 'IN_TRANSIT') as in_transit_max_cost, sum(case when status = 'IN_TRANSIT' then cost else 0 end) as in_transit_cost from latest group by date_trunc('quarter', shipped_date) having in_transit_cost > 0;
